-- A15/A16 forward-only account finalization foundation.
CREATE TYPE "FinancialYearStatus" AS ENUM ('OPEN', 'CLOSED');
CREATE TYPE "AccountImportStatus" AS ENUM ('UPLOADED','VALIDATED','READY','PROCESSING','COMPLETED','PARTIAL','FAILED','CANCELLED');
CREATE TYPE "PrintPaperSize" AS ENUM ('A4','THERMAL_80MM');
ALTER TYPE "CustomFieldEntity" ADD VALUE IF NOT EXISTS 'PROJECT';
ALTER TYPE "CustomFieldEntity" ADD VALUE IF NOT EXISTS 'ASSET';
ALTER TYPE "CustomFieldEntity" ADD VALUE IF NOT EXISTS 'QUOTATION';
ALTER TYPE "CustomFieldEntity" ADD VALUE IF NOT EXISTS 'SALES_INVOICE';
ALTER TYPE "CustomFieldEntity" ADD VALUE IF NOT EXISTS 'PURCHASE_BILL';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'IMPORT_VALIDATED';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'IMPORT_COMPLETED';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'RECORD_ARCHIVED';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'RECORD_RESTORED';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'FINANCIAL_YEAR_CLOSED';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'SETTINGS_CHANGED';
ALTER TYPE "AccountingAuditEventType" ADD VALUE IF NOT EXISTS 'BACKUP_GENERATED';
ALTER TABLE "financial_years" ADD COLUMN "status" "FinancialYearStatus" NOT NULL DEFAULT 'OPEN', ADD COLUMN "closedAt" TIMESTAMP(3), ADD COLUMN "closedById" UUID;
ALTER TABLE "account_settings" ADD COLUMN "transactionDefaults" JSONB, ADD COLUMN "projectDefaults" JSONB, ADD COLUMN "printProfile" JSONB;
CREATE TABLE "custom_field_values" ("id" UUID PRIMARY KEY, "companyId" UUID NOT NULL, "definitionId" UUID NOT NULL, "entityType" "CustomFieldEntity" NOT NULL, "entityId" UUID NOT NULL, "value" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "custom_field_values_companyId_definitionId_entityId_key" ON "custom_field_values"("companyId","definitionId","entityId"); CREATE INDEX "custom_field_values_companyId_entityType_entityId_idx" ON "custom_field_values"("companyId","entityType","entityId"); ALTER TABLE "custom_field_values" ADD CONSTRAINT "custom_field_values_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "custom_field_values" ADD CONSTRAINT "custom_field_values_definitionId_fkey" FOREIGN KEY ("definitionId") REFERENCES "custom_field_definitions"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE TABLE "account_import_jobs" ("id" UUID PRIMARY KEY, "companyId" UUID NOT NULL, "importType" VARCHAR(40) NOT NULL, "fileName" VARCHAR(255) NOT NULL, "fileHash" CHAR(64) NOT NULL, "status" "AccountImportStatus" NOT NULL DEFAULT 'UPLOADED', "rowCount" INTEGER NOT NULL DEFAULT 0, "validCount" INTEGER NOT NULL DEFAULT 0, "invalidCount" INTEGER NOT NULL DEFAULT 0, "createdById" UUID NOT NULL, "confirmedById" UUID, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3)); CREATE UNIQUE INDEX "account_import_jobs_companyId_importType_fileHash_key" ON "account_import_jobs"("companyId","importType","fileHash"); CREATE INDEX "account_import_jobs_companyId_createdAt_idx" ON "account_import_jobs"("companyId","createdAt"); ALTER TABLE "account_import_jobs" ADD CONSTRAINT "account_import_jobs_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE TABLE "account_recycle_records" ("id" UUID PRIMARY KEY, "companyId" UUID NOT NULL, "entityType" VARCHAR(40) NOT NULL, "entityId" UUID NOT NULL, "displayName" VARCHAR(240) NOT NULL, "archivedById" UUID NOT NULL, "archivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reason" TEXT, "restoredById" UUID, "restoredAt" TIMESTAMP(3)); CREATE UNIQUE INDEX "account_recycle_records_companyId_entityType_entityId_key" ON "account_recycle_records"("companyId","entityType","entityId"); CREATE INDEX "account_recycle_records_companyId_archivedAt_idx" ON "account_recycle_records"("companyId","archivedAt"); ALTER TABLE "account_recycle_records" ADD CONSTRAINT "account_recycle_records_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE TABLE "print_templates" ("id" UUID PRIMARY KEY, "companyId" UUID NOT NULL, "branchId" UUID, "documentType" VARCHAR(40) NOT NULL, "name" VARCHAR(120) NOT NULL, "paperSize" "PrintPaperSize" NOT NULL DEFAULT 'A4', "version" INTEGER NOT NULL DEFAULT 1, "isDefault" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "config" JSONB NOT NULL, "createdById" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "print_templates_companyId_branchId_documentType_name_version_key" ON "print_templates"("companyId","branchId","documentType","name","version"); CREATE INDEX "print_templates_companyId_documentType_paperSize_isDefault_isActive_idx" ON "print_templates"("companyId","documentType","paperSize","isDefault","isActive"); ALTER TABLE "print_templates" ADD CONSTRAINT "print_templates_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE TABLE "account_terms_templates" ("id" UUID PRIMARY KEY, "companyId" UUID NOT NULL, "branchId" UUID, "documentType" VARCHAR(40) NOT NULL, "name" VARCHAR(120) NOT NULL, "content" TEXT NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "account_terms_templates_companyId_documentType_isDefault_isActive_idx" ON "account_terms_templates"("companyId","documentType","isDefault","isActive"); ALTER TABLE "account_terms_templates" ADD CONSTRAINT "account_terms_templates_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE TABLE "account_backup_records" ("id" UUID PRIMARY KEY, "companyId" UUID NOT NULL, "generatedById" UUID NOT NULL, "manifest" JSONB NOT NULL, "checksum" CHAR(64) NOT NULL, "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "account_backup_records_companyId_generatedAt_idx" ON "account_backup_records"("companyId","generatedAt"); ALTER TABLE "account_backup_records" ADD CONSTRAINT "account_backup_records_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
